on conflict(country_code) do update set male_first_names=excluded.male_first_names,female_first_names=excluded.female_first_names,surnames=excluded.surnames,is_active=true,updated_at=now();

values ('US',12),('ES',11),('FR',11),('IT',10),('DE',10),('GB',10),('RS',9),('CZ',8),('PL',8),('HR',7),('AT',6),('CH',6),('NL',6),('BE',5),('SE',5),('NO',4),('DK',4),('FI',4),('GR',5),('PT',5),('RO',5),('BG',4),('HU',5),('SK',4),('SI',4),('BA',3),('MK',3),('CA',8),('MX',6),('AR',10),('BR',9),('CL',5),('CO',5),('PE',3),('UY',4),('AU',10),('NZ',5),('JP',8),('CN',8),('KR',6),('IN',6),('TH',4),('KZ',5),('UZ',3),('AE',2),('ZA',5),('MA',4),('TN',3),('EG',3),('KE',2),('NG',2)
on conflict(country_code) do update set players_per_world=excluded.players_per_world,updated_at=now();

do $$ declare v_total integer; begin
 select sum(players_per_world) into v_total from public.ai_country_distribution;
 if v_total<>300 then raise exception 'AI country distribution must total 300 per world, got %',v_total; end if;
end $$;

with country_order as(
 select d.country_code,d.players_per_world,p.male_first_names,p.female_first_names,p.surnames,row_number() over(order by d.country_code)::integer country_idx
 from public.ai_country_distribution d join public.ai_name_pools p using(country_code)
), candidates as(
 select c.*,w.world,gs.local_no,
 case when w.world='ATP' then c.male_first_names[mod(gs.local_no+c.country_idx*6-2,cardinality(c.male_first_names))+1]
      else c.female_first_names[mod(gs.local_no+c.country_idx*6-2,cardinality(c.female_first_names))+1] end first_name,
 c.surnames[mod(gs.local_no*3+c.country_idx*6+(case when w.world='ATP' then 0 else 2 end)-1,cardinality(c.surnames))+1] last_name
 from country_order c cross join lateral generate_series(1,c.players_per_world) gs(local_no) cross join (values('ATP'::text),('WTA'::text)) w(world)
), numbered as(
 select c.*,row_number() over(partition by world order by md5(world||':'||country_code||':'||local_no::text))::smallint ai_no from candidates c
), prepared as(
 select n.*,
 case when ai_no<=15 then 393+mod(ai_no*7,8) when ai_no<=90 then 381+mod(ai_no*5,12) when ai_no<=210 then 366+mod(ai_no*7,15) else 350+mod(ai_no*9,16) end::smallint technical_total,
 (176+mod(ai_no*7+(case when world='ATP' then 3 else 11 end),21))::smallint physical_total,
 case mod(ai_no*7,20) when 0 then 'Grass' when 1 then 'Grass' when 2 then 'Grass' when 3 then 'Clay' when 4 then 'Clay' when 5 then 'Clay' when 6 then 'Clay' when 7 then 'Clay' when 8 then 'Clay' else 'Hard' end preferred_surface,
 case when mod(ai_no*11,10)<4 then 'All-court' when mod(ai_no*11,10)<7 then 'Aggressive Baseliner' when mod(ai_no*11,10)<9 then 'Defensive Baseliner' else 'Serve & Volley' end playing_style
 from numbered n
), with_city as(
 select p.*,h.city home_city from prepared p
 join lateral(select city from public.player_home_city_options h where h.country_code=p.country_code and h.is_active order by h.sort_order offset mod(p.local_no+p.ai_no-2,10) limit 1) h on true
)
select null,world,first_name,last_name,country_code,home_city,null,'approved',preferred_surface,playing_style,'ai',ai_no,technical_total,physical_total
from with_city
where not exists(select 1 from public.players p where p.world=with_city.world and p.player_type='ai' and p.ai_profile_number=with_city.ai_no)
order by world,ai_no;

do $$ declare v_atp integer; v_wta integer; v_dups integer; begin
 select count(*) into v_atp from public.players where player_type='ai' and world='ATP';
 select count(*) into v_wta from public.players where player_type='ai' and world='WTA';
 select count(*) into v_dups from(select world,lower(first_name),lower(last_name),count(*) from public.players where player_type='ai' group by world,lower(first_name),lower(last_name) having count(*)>1)x;
 if v_atp<>300 or v_wta<>300 then raise exception 'Expected 300 ATP and 300 WTA AI players, got % and %',v_atp,v_wta; end if;
 if v_dups<>0 then raise exception 'Duplicate AI names detected: %',v_dups; end if;
end $$;

with d as(select * from public.get_current_game_day_internal_v1())
update public.ai_simulation_state set last_training_absolute_day=public.game_day_absolute_v1(d.season,d.month,d.day)-1,updated_at=now()
from d where singleton=true;
